//! Rust types for the daemon WebSocket protocol, generated by `build.rs` from the zod schemas in
//! `packages/protocol` (ADR-0035). Refresh them with `codegen/export-schema.mjs`.
//!
//! Decoding follows the protocol contract: unknown fields are ignored, and a message type this
//! client does not know decodes to the `Unrecognized` variant instead of failing the frame.

/// Every generated type. Names come from the message tags (`agent_stream` -> `AgentStream`) and
/// the property path; prefer the stable names below where one exists.
#[allow(clippy::all, dead_code, unused_imports, irrefutable_let_patterns)]
pub mod generated {
    include!(concat!(env!("OUT_DIR"), "/protocol.rs"));
}

/// The `server_info` status payload, the daemon's answer to `hello`. The session envelope
/// types status payloads as an open object; decode this one with `decode_server_info`.
pub use generated::ServerInfo;
/// The client to daemon envelope: `ping`, `hello`, `recording_state`, or `session`.
pub use generated::WsInbound;
/// The daemon to client envelope: `pong`, `session`, or `hello.rejected`.
pub use generated::WsOutbound;
/// The `message` of an inbound `session` envelope.
pub type SessionInbound = generated::WsInboundSessionMessage;
/// The `message` of an outbound `session` envelope.
pub type SessionOutbound = generated::WsOutboundSessionMessage;

/// The protocol version this client sends in `hello`.
pub const PROTOCOL_VERSION: u32 = 1;

/// Decodes one text frame from the daemon.
pub fn decode_outbound(text: &str) -> Result<WsOutbound, serde_json::Error> {
    serde_json::from_str(text)
}

/// Decodes the `payload` of a `status` message whose `status` is `server_info`.
pub fn decode_server_info(payload: &serde_json::Value) -> Result<ServerInfo, serde_json::Error> {
    <ServerInfo as serde::Deserialize>::deserialize(payload)
}

/// Encodes one text frame for the daemon.
pub fn encode_inbound(message: &WsInbound) -> String {
    serde_json::to_string(message).expect("generated protocol types always serialize to JSON")
}
